package main

import "fmt"

func fib(n int) int {
	a, b := 0, 1
	for i := 0; i < n; i++ {
		a, b = b, a+b
	}
	return a
}

func gcd(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

func isPrime(n int) bool {
	if n < 2 {
		return false
	}
	for i := 2; i*i <= n; i++ {
		if n%i == 0 {
			return false
		}
	}
	return true
}

func primesBelow(limit int) []int {
	var primes []int
	for n := 2; n < limit; n++ {
		if isPrime(n) {
			primes = append(primes, n)
		}
	}
	return primes
}

func binarySearch(items []int, target int) int {
	lo, hi := 0, len(items)-1
	for lo <= hi {
		mid := (lo + hi) / 2
		switch {
		case items[mid] == target:
			return mid
		case items[mid] < target:
			lo = mid + 1
		default:
			hi = mid - 1
		}
	}
	return -1
}

func main() {
	fmt.Println("fib(10) =", fib(10))
	fmt.Println("gcd(54, 24) =", gcd(54, 24))
	fmt.Println("primes:", primesBelow(50))

	squares := make([]int, 19)
	for i := range squares {
		squares[i] = (i + 1) * (i + 1)
	}
	fmt.Println("index of 144:", binarySearch(squares, 144))
}

